// Eingangspruefung, bevor ein Token verbrannt wird. Drei Faelle laufen sonst
// regelmaessig in teure Leerlaeufe: leere Nachrichten aus Tippfeldern,
// Copy-Paste-Romane und fehlende Session-IDs (ohne die laesst sich ein
// Gespraech spaeter nicht mehr nachvollziehen).
const MIN_ZEICHEN = 5;
const MAX_ZEICHEN = 1500;

const body = $input.first().json.body ?? $input.first().json;
const frage = String(body.frage ?? body.message ?? '').trim();
const session = String(body.session_id ?? '').trim();

const maengel = [];
if (frage.length < MIN_ZEICHEN) maengel.push('Die Frage ist zu kurz. Bitte in einem ganzen Satz beschreiben, worum es geht.');
if (frage.length > MAX_ZEICHEN) maengel.push('Die Nachricht ist sehr lang. Bitte auf eine konkrete Frage kuerzen.');
if (!session) maengel.push('Es fehlt eine Session-Kennung.');

return [{
  json: {
    frage: frage.slice(0, MAX_ZEICHEN),
    session_id: session || ('unbekannt-' + Date.now()),
    kanal: body.kanal ?? 'Website-Chat',
    kunde_id: body.kunde_id ?? null,
    eingang_iso: new Date().toISOString(),
    eingang_de: new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    maengel,
    verwertbar: maengel.length === 0
  }
}];

// Die Suchtreffer werden hier in einen nummerierten Kontext gegossen, damit der
// Agent im Text auf [1], [2] verweisen kann - nur so laesst sich die Antwort
// spaeter gegen die Quelle pruefen.
// Erwartetes Format der Such-API (bei abweichender API hier anpassen):
//   { treffer: [ { titel, text, quelle, score } ] }
const anfrage = $('Anfrage pruefen').first().json;
const antwort = $input.first().json;
const roh = antwort.treffer ?? antwort.results ?? antwort.matches ?? [];

const treffer = (Array.isArray(roh) ? roh : []).map((t, i) => ({
  nummer: i + 1,
  titel: t.titel ?? t.title ?? ('Dokument ' + (i + 1)),
  quelle: t.quelle ?? t.url ?? t.source ?? '',
  score: Number(t.score ?? t.relevanz ?? 0),
  // Lange Dokumente kappen: der Agent bekommt sonst mehr Kontext, als er
  // sauber verarbeiten kann, und die Antwortzeit im Chat wird spuerbar.
  text: String(t.text ?? t.content ?? t.inhalt ?? '').slice(0, 1500)
}));

const kontext = treffer.length
  ? treffer.map(t => `[${t.nummer}] ${t.titel} (Relevanz ${t.score.toFixed(2)})\nQuelle: ${t.quelle}\n${t.text}`).join('\n\n')
  : '(keine passenden Eintraege in der Wissensbasis gefunden)';

return [{
  json: {
    ...anfrage,
    trefferzahl: treffer.length,
    bester_score: treffer.length ? Math.max(...treffer.map(t => t.score)) : 0,
    treffer,
    kontext
  }
}];

