// Hier entscheidet sich, ob der Bot antwortet oder abgibt. Drei Gruende fuehren
// zur Uebergabe an einen Menschen - alle drei sind in der Praxis die Faelle, in
// denen ein Chatbot sonst selbstbewusst Unsinn erzaehlt:
//   1. Die Wissensbasis hatte keine Treffer.
//   2. Das Modell gibt selbst eine niedrige Konfidenz an.
//   3. Die Antwort nennt keine Quelle - dann steht sie auf keiner Grundlage.
// Zusaetzlich faengt der try/catch den Fall ab, dass der Agent kein sauberes
// JSON liefert: auch das ist ein Uebergabefall und kein Grund zum Raten.
const MINDESTKONFIDENZ = 0.75;
const basis = $('Treffer aufbereiten').first().json;
const roh = $input.first().json;

let a = {};
let parsefehler = null;
try {
  a = typeof roh.output === 'string' ? JSON.parse(roh.output) : (roh.output ?? roh);
} catch (e) {
  parsefehler = 'Antwort des Modells war kein gueltiges JSON';
}

const konfidenz = Number(a.konfidenz ?? 0);
const genutzteQuellen = Array.isArray(a.quellen) ? a.quellen : [];
// Nur Quellennummern zulassen, die es wirklich gab - erfundene Fussnoten sind
// sonst nicht von echten zu unterscheiden.
const belege = basis.treffer.filter(t => genutzteQuellen.includes(t.nummer));

const gruende = [];
if (parsefehler) gruende.push(parsefehler);
if (basis.trefferzahl === 0) gruende.push('Kein passender Eintrag in der Wissensbasis');
if (konfidenz < MINDESTKONFIDENZ) gruende.push(`Konfidenz ${konfidenz.toFixed(2)} unter Schwelle ${MINDESTKONFIDENZ}`);
if (belege.length === 0) gruende.push('Antwort nennt keine belegbare Quelle');

return [{
  json: {
    session_id: basis.session_id,
    kanal: basis.kanal,
    kunde_id: basis.kunde_id,
    frage: basis.frage,
    eingang_de: basis.eingang_de,
    antwort_ki: String(a.antwort ?? '').trim(),
    rueckfrage: a.rueckfrage ?? null,
    konfidenz,
    begruendung: a.begruendung ?? '',
    belege,
    quellen_text: belege.map(b => `${b.titel}${b.quelle ? ' (' + b.quelle + ')' : ''}`).join(' | '),
    trefferzahl: basis.trefferzahl,
    uebergabe_gruende: gruende,
    belastbar: gruende.length === 0
  }
}];

